//! OrcaSlicer 設定バンドル/プロファイル (`*.ini`) の検出・カウント。
//!
//! PrusaSlicer 派生だが `# generated by OrcaSlicer` ヘッダと、
//! `print_sequence`/`auto_calibrate`/`curr_bed_type`/`machine_pause_gcode`/
//! `preheat_time` 等の OrcaSlicer 固有キーを持つ。
//!
//! ```
//! let cfg = b"# generated by OrcaSlicer 2.0\n\n[printer]\nprinter_model = K1\n\
//!             nozzle_diameter = 0.4\nauto_calibrate = 0\ncurr_bed_type = Textured PEI Plate\n\
//!             machine_pause_gcode = M400 U1\n";
//! assert!(izanagi_kit::orcaslicer::detect(cfg));
//! let c = izanagi_kit::orcaslicer::parse(cfg).unwrap();
//! assert_eq!(c.entries, 5);
//! assert_eq!(c.orca_entries, 4);
//! assert_eq!(c.slicer_entries, 1);
//! ```

