/// セクション名の接頭辞。
const SECTION_HEADS: &[&str] = &[
    "print",
    "filament",
    "printer",
    "vendor",
    "presets",
    "sla_print",
    "sla_material",
];

fn key_of(s: &str) -> Option<(&str, &str)> {
    let i = s.find('=')?;
    let k = s[..i].trim();
    if k.is_empty() || !k.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_') {
        return None;
    }
    Some((k, s[i + 1..].trim()))
}

/// カウント結果。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Counts {
    /// `[print]`/`[filament]`/`[print:名前]` 等のセクション数。
    pub sections: usize,
    /// 既知キーの `key = value` 行数。
    pub entries: usize,
    /// OrcaSlicer 固有キーの行数。
    pub orca_entries: usize,
    /// PrusaSlicer 共有キーの行数。
    pub slicer_entries: usize,
    /// `*gcode` キーの行数。
    pub gcode_entries: usize,
    /// `generated by OrcaSlicer` ヘッダの有無 (0/1)。
    pub marker: usize,
    /// `#`/`;` コメント行数。
    pub comments: usize,
}

/// `b` が OrcaSlicer `*.ini` 形式かどうか。
#[must_use]
pub fn detect(b: &[u8]) -> bool {
    let Some(c) = parse(b) else {
        return false;
    };
    c.marker >= 1 || (c.orca_entries >= 2 && c.slicer_entries >= 1)
}

/// `b` を OrcaSlicer `*.ini` として解析し、行種別をカウントする。
#[must_use]
pub fn parse(b: &[u8]) -> Option<Counts> {
    let text = std::str::from_utf8(b).ok()?;
    let mut c = Counts {
        sections: 0,
        entries: 0,
        orca_entries: 0,
        slicer_entries: 0,
        gcode_entries: 0,
        marker: 0,
        comments: 0,
    };
    for line in text.lines() {
        let s = line.trim();
        if s.is_empty() {
            continue;
        }
        if s.starts_with('#') || s.starts_with(';') {
            c.comments += 1;
            if s.contains("OrcaSlicer") {
                c.marker = 1;
            }
            continue;
        }
        if s.starts_with('[') {
            let inner = s
                .strip_prefix('[')
                .unwrap_or(s)
                .split(']')
                .next()
                .unwrap_or("")
                .trim();
            let head = inner.split(':').next().unwrap_or("");
            if SECTION_HEADS.contains(&head) {
                c.sections += 1;
            }
            continue;
        }
        if let Some((k, _v)) = key_of(s) {
            let orca = ORCA_KEYS.contains(&k);
            let slicer = SLICER_KEYS.contains(&k);
            if !orca && !slicer {
                continue;
            }
            c.entries += 1;
            if orca {
                c.orca_entries += 1;
            } else {
                c.slicer_entries += 1;
            }
            if k.ends_with("gcode") {
                c.gcode_entries += 1;
            }
        }
    }
    if c.entries == 0 && c.marker == 0 {
        return None;
    }
    Some(c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_generated_header() {
        assert!(detect(b"# generated by OrcaSlicer 2.1.0\n\n[printer]\n"));
    }

    #[test]
    fn detects_orca_keys() {
        let cfg = b"[print:0.20 Standard]\nprint_sequence = by layer\nauto_calibrate = 1\n\
                    layer_height = 0.2\nmachine_pause_gcode = M400 U1\n";
        assert!(detect(cfg));
        let c = parse(cfg).unwrap();
        assert_eq!(c.orca_entries, 3);
        assert_eq!(c.slicer_entries, 1);
    }

    #[test]
    fn rejects_prusaslicer() {
        // PrusaSlicer のみのキー構成では OrcaSlicer と判定しない
        assert!(!detect(
            b"[printer]\nlayer_height = 0.2\nnozzle_diameter = 0.4\nbed_temperature = 60\n"
        ));
    }
}
